{
  semilla;
  const k = nTrat, r = nRep;
  const colores = ["#01696f","#964219","#437a22","#006494","#7a39bb","#a12c7b"];
  const trts = Array.from({length: k}, (_, i) =&gt; `T${i+1}`);

  function shuffle(arr) {
    let a = [...arr];
    for (let i = a.length - 1; i &gt; 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  const w = 52, h = 52, gap = 6, pad = 44;
  const cols = tipoDiseno === "DCA" ? Math.ceil(Math.sqrt(k * r)) : k;
  const rows = tipoDiseno === "DCA" ? Math.ceil((k * r) / cols) : r;
  const svgW = cols * (w + gap) + pad * 2;
  const svgH = rows * (h + gap) + pad * 2 + 30;

  let celdas = [];
  if (tipoDiseno === "DCA") {
    const todas = [];
    for (let i = 0; i &lt; r; i++) trts.forEach(t =&gt; todas.push(t));
    shuffle(todas).forEach((t, idx) =&gt; {
      celdas.push({t, col: idx % cols, row: Math.floor(idx / cols)});
    });
  } else {
    for (let b = 0; b &lt; r; b++)
      shuffle(trts).forEach((t, ci) =&gt; celdas.push({t, col: ci, row: b}));
  }

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${svgW} ${svgH}`)
    .attr("width", "100%")
    .style("max-width", `${svgW}px`)
    .style("font-family", "sans-serif");

  if (tipoDiseno === "DBCA") {
    for (let b = 0; b &lt; r; b++) {
      svg.append("rect")
        .attr("x", pad - 4).attr("y", pad + b * (h + gap) - 4)
        .attr("width", cols * (w + gap) + 2).attr("height", h + 8)
        .attr("rx", 6).attr("fill", b % 2 === 0 ? "#f3f0ec" : "#e6e4df")
        .attr("stroke", "#dcd9d5").attr("stroke-width", 1);
      svg.append("text")
        .attr("x", pad - 8).attr("y", pad + b * (h + gap) + h / 2 + 5)
        .attr("text-anchor", "end").attr("font-size", 11).attr("fill", "#7a7974")
        .text(`B${b+1}`);
    }
  }

  celdas.forEach(({t, col, row}) =&gt; {
    const x = pad + col * (w + gap), y = pad + row * (h + gap);
    const ci = trts.indexOf(t);
    svg.append("rect").attr("x", x).attr("y", y).attr("width", w).attr("height", h)
      .attr("rx", 7).attr("fill", colores[ci] + "22")
      .attr("stroke", colores[ci]).attr("stroke-width", 2);
    svg.append("text").attr("x", x + w/2).attr("y", y + h/2 + 5)
      .attr("text-anchor", "middle").attr("font-size", 14).attr("font-weight", "600")
      .attr("fill", colores[ci]).text(t);
  });

  const lyY = svgH - 12;
  trts.forEach((t, i) =&gt; {
    const lx = pad + i * 70;
    svg.append("rect").attr("x", lx).attr("y", lyY - 10)
      .attr("width", 14).attr("height", 14).attr("rx", 3)
      .attr("fill", colores[i] + "33").attr("stroke", colores[i]).attr("stroke-width", 1.5);
    svg.append("text").attr("x", lx + 18).attr("y", lyY + 1)
      .attr("font-size", 12).attr("fill", "#28251d").text(t);
  });

  return svg.node();
}









8.4.2 Repetición
La repetición consiste en aplicar cada tratamiento a varias unidades experimentales independientes. Gracias a la repetición es posible estimar el error experimental y aumentar la precisión de las comparaciones entre tratamientos.






Tip¿Por qué es importante la repetición?




Permite estimar el error experimental.
Mejora la precisión de las medias de tratamiento.
Aumenta la capacidad para detectar diferencias reales.
Hace más robustas las conclusiones del experimento.



Ejemplo: si se desea comparar cuatro variedades de maíz, no es suficiente sembrar una sola parcela por variedad. Se necesitan varias parcelas para cada variedad.


8.4.3 Bloqueo
El bloqueo o control local consiste en agrupar unidades experimentales similares en bloques y asignar los tratamientos dentro de cada bloque. Su objetivo es controlar fuentes conocidas de variación que podrían afectar la respuesta del experimento.






Tip¿Por qué es importante el bloqueo?




Controla fuentes conocidas de variación.
Reduce el error experimental.
Mejora la precisión de las comparaciones.
Hace más eficiente el experimento cuando el material no es completamente homogéneo.



Ejemplo: si un lote presenta un gradiente de fertilidad de un extremo al otro, puede dividirse en bloques perpendiculares a ese gradiente. Luego, dentro de cada bloque, se asignan aleatoriamente los tratamientos.
